window.CIVIL_SET_DATA["past-12"] = {"title":"Past Paper Set 12","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-12-004","src":"PAST-12-004","text":"The CG of a (solid) cone from its base is at","options":[{"key":"a","text":"h/3"},{"key":"b","text":"h/4"},{"key":"c","text":"h/2"},{"key":"d","text":"3h/4"}],"answer":"b","explanation":"The centroid of a solid cone lies on its axis at h/4 above the base (3h/4 from the apex). For a hollow conical shell it is h/3.","marks":1,"source":{"kind":"past","set":12,"question":4,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q4 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-12-014","src":"PAST-12-014","text":"The effect on timber due to electric seasoning is","options":[{"key":"a","text":"Splitting"},{"key":"b","text":"Cracking"},{"key":"c","text":"Rot"},{"key":"d","text":"Check"}],"answer":"a","explanation":"Electric (high-frequency) seasoning dries timber very quickly from the inside, and the rapid moisture loss makes it liable to split. The method is costly and is used only for special work.","marks":1,"source":{"kind":"past","set":12,"question":14,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q14 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-12-049","src":"PAST-12-049","text":"What is the composition of quartzite?","options":[{"key":"a","text":"calcareous"},{"key":"b","text":"siliceous"},{"key":"c","text":"argillaceous"},{"key":"d","text":"none of the above"}],"answer":"b","explanation":"Quartzite is metamorphosed sandstone, composed almost entirely of silica (quartz), so it is a siliceous rock.","marks":1,"source":{"kind":"past","set":12,"question":49,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q49 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-12-053","src":"PAST-12-053","text":"The component of paint that imparts colour to it is called","options":[{"key":"a","text":"pigment"},{"key":"b","text":"vehicle"},{"key":"c","text":"both"},{"key":"d","text":"none"}],"answer":"a","explanation":"Pigments (for example zinc oxide, titanium dioxide, iron oxides) give paint its colour and body. The vehicle (oil) carries them and forms the film.","marks":1,"source":{"kind":"past","set":12,"question":53,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q53 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-12-055","src":"PAST-12-055","text":"In the long wall - short wall method, the length of the long wall is the sum of the centre line length and","options":[{"key":"a","text":"b/2"},{"key":"b","text":"b/4"},{"key":"c","text":"b"},{"key":"d","text":"2b"}],"answer":"c","explanation":"The long wall (out-to-out) is the centre-line length plus the wall width \\(b\\) (\\(\\dfrac{b}{2}\\) at each end). The short wall (in-to-in) is the centre-line length minus \\(b\\).","marks":1,"source":{"kind":"past","set":12,"question":55,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q55 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-12-057","src":"PAST-12-057","text":"For 1st class bricks, the water absorption should not be more than","options":[{"key":"a","text":"10%"},{"key":"b","text":"15%"},{"key":"c","text":"20%"},{"key":"d","text":"30%"}],"answer":"b","explanation":"The key follows the classification in which first-class bricks absorb not more than about 15% of their dry weight after 24 hours in water (some texts allow up to 20%).","marks":1,"source":{"kind":"past","set":12,"question":57,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q57 · 1 mark"},"topic":"ACiE0102"},{"id":"PAST-12-063","src":"PAST-12-063","text":"Given that the carpet area of a floor is 100 m<sup>2</sup>, the circulation area is 50% of the plinth area and the rate per sq. m of plinth area is Rs. 40,000, what is the total estimate of the building?","options":[{"key":"a","text":"80 lakhs"},{"key":"b","text":"8 lakhs"},{"key":"c","text":"120 lakhs"},{"key":"d","text":"60 lakhs"}],"answer":"a","explanation":"If circulation takes 50% of the plinth area, the carpet area is the other 50%, so the plinth area is 200 m<sup>2</sup>. The cost is \\[200 \\times 40{,}000 = \\text{Rs } 80\\ \\text{lakh}\\]","marks":2,"source":{"kind":"past","set":12,"question":63,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q63 · 2 marks"},"topic":"ACiE0106"},{"id":"PAST-12-072","src":"PAST-12-072","text":"Calculate the second moment of area of a hollow circular section with external and internal diameters of 20 cm and 10 cm respectively.","options":[{"key":"a","text":"2,347 cm<sup>4</sup>"},{"key":"b","text":"3,681 cm<sup>4</sup>"},{"key":"c","text":"7,363 cm<sup>4</sup>"},{"key":"d","text":"9,375 cm<sup>4</sup>"}],"answer":"c","explanation":"The second moment of area is \\[\\begin{aligned} I &amp;= \\dfrac{\\pi(D^4 - d^4)}{64} \\\\ &amp;= \\dfrac{\\pi(160{,}000 - 10{,}000)}{64} \\\\ &amp;\\approx 7363\\ \\text{cm}^4 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":12,"question":72,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q72 · 2 marks"},"topic":"ACiE0104"},{"id":"PAST-12-075","src":"PAST-12-075","text":"Le-Chatelier's device is used for determining the","options":[{"key":"a","text":"setting time of cement"},{"key":"b","text":"tensile strength"},{"key":"c","text":"soundness"},{"key":"d","text":"compressive strength"}],"answer":"c","explanation":"The Le Chatelier apparatus measures the expansion of cement paste after boiling, which is its soundness (limit 10 mm for OPC). This detects excess free lime.","marks":2,"source":{"kind":"past","set":12,"question":75,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q75 · 2 marks"},"topic":"ACiE0102"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-12-009","src":"PAST-12-009","text":"What is the formula for seepage discharge in a flow net?","options":[{"key":"a","text":"Δq = k·H·(N<sub>f</sub>/N<sub>d</sub>)"},{"key":"b","text":"Δq = k·H·N<sub>f</sub>"},{"key":"c","text":"Δq = k·H·N<sub>d</sub>"},{"key":"d","text":"Δq = k·H·(N<sub>d</sub>/N<sub>f</sub>)"}],"answer":"a","explanation":"The total seepage per unit length is \\[q = kH\\dfrac{N_f}{N_d}\\] where \\(N_f\\) is the number of flow channels and \\(N_d\\) the number of potential drops. Each channel carries \\(\\Delta q = \\dfrac{kH}{N_d}\\).","marks":1,"source":{"kind":"past","set":12,"question":9,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q9 · 1 mark"},"topic":"ACiE0202"},{"id":"PAST-12-013","src":"PAST-12-013","text":"If there are 2 or more columns in a foundation, what is the name of the foundation?","options":[{"key":"a","text":"Combined footing"},{"key":"b","text":"Mat foundation"},{"key":"c","text":"Raft footing"},{"key":"d","text":"Pile foundation"}],"answer":"a","explanation":"A combined footing supports two (or a few) columns in a line on one base. A mat or raft carries all the columns of the building.","marks":1,"source":{"kind":"past","set":12,"question":13,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q13 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-12-051","src":"PAST-12-051","text":"How will the water table affect the effective stress if it rises above GL?","options":[{"key":"a","text":"effective stress increases"},{"key":"b","text":"effective stress decreases"},{"key":"c","text":"no effect"},{"key":"d","text":"effective stress may increase or decrease"}],"answer":"c","explanation":"Once the water is above the ground, any further rise adds equally to total stress and pore pressure, so the effective stress in the soil is unchanged.","marks":1,"source":{"kind":"past","set":12,"question":51,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q51 · 1 mark"},"topic":"ACiE0202"},{"id":"PAST-12-054","src":"PAST-12-054","text":"The bearing capacity depends upon","options":[{"key":"a","text":"soil type"},{"key":"b","text":"type of foundation"},{"key":"c","text":"water table depth"},{"key":"d","text":"all of the above"}],"answer":"d","explanation":"Bearing capacity depends on the soil's shear strength and density (soil type), the size, shape and depth of the foundation, and the position of the water table.","marks":1,"source":{"kind":"past","set":12,"question":54,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q54 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-12-061","src":"PAST-12-061","text":"The minimum depth of foundation according to Rankine's formula will be (given q = 180 kN/m<sup>2</sup>, γ = 20 kN/m<sup>3</sup> and φ = 30°)","options":[{"key":"a","text":"0.8 m"},{"key":"b","text":"8 m"},{"key":"c","text":"1 m"},{"key":"d","text":"0.5 m"}],"answer":"c","explanation":"Rankine's formula gives \\[D = \\dfrac{q}{\\gamma}\\left(\\dfrac{1 - \\sin\\phi}{1 + \\sin\\phi}\\right)^2\\] \\[= 9 \\times \\left(\\dfrac{1}{3}\\right)^2 = 1.0\\ \\text{m}\\]","marks":2,"source":{"kind":"past","set":12,"question":61,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q61 · 2 marks"},"topic":"ACiE0205"},{"id":"PAST-12-074","src":"PAST-12-074","text":"Which of the following is not among the common types of mat foundation?","options":[{"key":"a","text":"Flat plate type"},{"key":"b","text":"Box structures"},{"key":"c","text":"Mats on piles"},{"key":"d","text":"Double flat plate thickness"}],"answer":"d","explanation":"Common rafts are the flat plate, the flat plate thickened under columns, beam-and-slab, box (cellular) rafts and piled rafts. 'Double flat plate thickness' is not a standard type.","marks":2,"source":{"kind":"past","set":12,"question":74,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q74 · 2 marks"},"topic":"ACiE0205"},{"id":"PAST-12-077","src":"PAST-12-077","text":"If the bearing stress is 180 kN/m<sup>2</sup>, unit weight = 20 kN/m<sup>3</sup> and internal angle of friction = 30 degree, then according to Rankine's theory what is the minimum depth of foundation?","options":[{"key":"a","text":"1 m"},{"key":"b","text":"0.8 m"},{"key":"c","text":"2 m"},{"key":"d","text":"0.5 m"}],"answer":"a","explanation":"Rankine's minimum depth is \\[D_{min} = \\dfrac{q}{\\gamma}\\left(\\dfrac{1 - \\sin\\phi}{1 + \\sin\\phi}\\right)^2\\] \\[= \\dfrac{180}{20}\\left(\\dfrac{1}{3}\\right)^2 = 1\\ \\text{m}\\]","marks":2,"source":{"kind":"past","set":12,"question":77,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q77 · 2 marks"},"topic":"ACiE0205"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-12-006","src":"PAST-12-006","text":"The equation of continuity for a fluid that is compressible and flow that is steady is","options":[{"key":"a","text":"A<sub>1</sub>V<sub>1</sub> = A<sub>2</sub>V<sub>2</sub>"},{"key":"b","text":"ρ<sub>1</sub>A<sub>1</sub>V<sub>1</sub> = ρ<sub>2</sub>A<sub>2</sub>V<sub>2</sub>"},{"key":"c","text":"A<sub>1</sub>V<sub>2</sub> = A<sub>2</sub>V<sub>1</sub>"},{"key":"d","text":"A<sub>1</sub>V<sub>1</sub> = A<sub>2</sub>V<sub>2</sub>ρ"}],"answer":"b","explanation":"In steady flow the mass flow rate is constant: \\[\\rho_1A_1V_1 = \\rho_2A_2V_2\\] It reduces to \\(A_1V_1 = A_2V_2\\) only when the density is constant.","marks":1,"source":{"kind":"past","set":12,"question":6,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q6 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-12-007","src":"PAST-12-007","text":"When the barometer reads 740.0 mm of mercury, a pressure of 10 kPa suction at that location is equivalent to","options":[{"key":"a","text":"10.02 m of water (abs)"},{"key":"b","text":"9.87 m of water (abs)"},{"key":"c","text":"88.72 kPa (abs)"},{"key":"d","text":"0.043 kPa (abs)"}],"answer":"c","explanation":"The atmospheric pressure is \\[\\begin{aligned} p_{atm} &amp;= 0.740 \\times 13{,}600 \\times 9.81 \\\\ &amp;\\approx 98.7\\ \\text{kPa} \\end{aligned}\\] so \\[p_{abs} = 98.7 - 10 \\approx 88.7\\ \\text{kPa}\\]","marks":1,"source":{"kind":"past","set":12,"question":7,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q7 · 1 mark"},"topic":"ACiE0302"},{"id":"PAST-12-008","src":"PAST-12-008","text":"e/D is a parameter in the Moody diagram. What is e in the Moody diagram?","options":[{"key":"a","text":"viscosity"},{"key":"b","text":"kinematic viscosity"},{"key":"c","text":"surface roughness height"},{"key":"d","text":"boundary layer thickness"}],"answer":"c","explanation":"e is the average height of the roughness projections on the pipe wall, and e/D is the relative roughness used with Re to read the friction factor.","marks":1,"source":{"kind":"past","set":12,"question":8,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q8 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-12-062","src":"PAST-12-062","text":"The recession limb of a hydrograph is independent of","options":[{"key":"a","text":"basin characteristics"},{"key":"b","text":"storm characteristics"},{"key":"c","text":"both"},{"key":"d","text":"none"}],"answer":"b","explanation":"The recession limb represents drainage of water already stored in the basin, so it depends on basin characteristics and is independent of the storm that caused it.","marks":2,"source":{"kind":"past","set":12,"question":62,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q62 · 2 marks"},"topic":"ACiE0306"},{"id":"PAST-12-067","src":"PAST-12-067","text":"What is the specific gravity of a block if its weight in air is 60 N and its weight when immersed in water is 40 N?","options":[{"key":"a","text":"3"},{"key":"b","text":"5"},{"key":"c","text":"0.666"},{"key":"d","text":"0.333"}],"answer":"a","explanation":"The loss of weight, 20 N, equals the buoyancy (weight of an equal volume of water), so \\[G = \\dfrac{60}{20} = 3\\]","marks":2,"source":{"kind":"past","set":12,"question":67,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q67 · 2 marks"},"topic":"ACiE0302"},{"id":"PAST-12-071","src":"PAST-12-071","text":"The area of a triangular section is 66.72 m<sup>2</sup> and the wetted perimeter of the section is 24.03 m. Calculate the value of Manning's rugosity if the bed slope of the channel is 1:500 and the discharge through the channel is 117.6 cumec.","options":[{"key":"a","text":"0.03"},{"key":"b","text":"0.04"},{"key":"c","text":"0.05"},{"key":"d","text":"0.06"}],"answer":"c","explanation":"The hydraulic radius is \\(R = \\dfrac{66.72}{24.03} = 2.78\\) m, so \\[\\begin{aligned} n &amp;= \\dfrac{AR^{2{/}3}S^{1{/}2}}{Q} \\\\ &amp;= \\dfrac{66.72 \\times 1.975 \\times 0.0447}{117.6} \\\\ &amp;\\approx 0.05 \\end{aligned}\\] (The paper writes 'cusec'; cumec is intended.)","marks":2,"source":{"kind":"past","set":12,"question":71,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q71 · 2 marks"},"topic":"ACiE0305"},{"id":"PAST-12-073","src":"PAST-12-073","text":"The sequent depths in a hydraulic jump occurring in a horizontal rectangular channel are 0.25 m and 1.25 m. The energy lost in this jump is","options":[{"key":"a","text":"0.8 m"},{"key":"b","text":"1.0 m"},{"key":"c","text":"1.25 m"},{"key":"d","text":"1.5 m"}],"answer":"a","explanation":"The energy lost in the jump is \\[\\begin{aligned} E_L &amp;= \\dfrac{(y_2 - y_1)^3}{4y_1y_2} \\\\ &amp;= \\dfrac{1^3}{4 \\times 0.25 \\times 1.25} \\\\ &amp;= 0.8\\ \\text{m} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":12,"question":73,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q73 · 2 marks"},"topic":"ACiE0305"},{"id":"PAST-12-078","src":"PAST-12-078","text":"Given a Gumbel's distribution with μ = 0 and β = 1, find the probability that X is less than or equal to 2.","options":[{"key":"a","text":"0.864"},{"key":"b","text":"0.564"},{"key":"c","text":"1.124"},{"key":"d","text":"0.665"}],"answer":"a","explanation":"The Gumbel CDF is \\[F(x) = \\exp\\left[-e^{-(x - \\mu){/}\\beta}\\right]\\] so \\[\\begin{aligned} F(2) &amp;= \\exp(-e^{-2}) \\\\ &amp;= \\exp(-0.135) \\approx 0.87 \\end{aligned}\\] The nearest option is 0.864 (and 1.124 is impossible for a probability).","marks":2,"source":{"kind":"past","set":12,"question":78,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q78 · 2 marks"},"topic":"ACiE0306"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-12-005","src":"PAST-12-005","text":"If a bending moment M acts at each support of a simply supported beam (equal end moments), the SFD has ordinates","options":[{"key":"a","text":"zero at all sections"},{"key":"b","text":"max at mid-point"},{"key":"c","text":"max at supports"},{"key":"d","text":"zero at the supports"}],"answer":"a","explanation":"Equal end moments put the beam in pure bending: the moment is constant (M) along the span, so the shear force is zero everywhere.","marks":1,"source":{"kind":"past","set":12,"question":5,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q5 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-12-010","src":"PAST-12-010","text":"The deflection at the centre of a simply supported beam when a concentrated load P acts at its centre is","options":[{"key":"a","text":"PL<sup>3</sup>/48EI"},{"key":"b","text":"PL<sup>3</sup>/96EI"},{"key":"c","text":"PL<sup>4</sup>/24EI"},{"key":"d","text":"PL<sup>2</sup>/24EI"}],"answer":"a","explanation":"For a central point load, \\[\\delta_{max} = \\dfrac{PL^3}{48EI}\\] and the end slopes are \\(\\dfrac{PL^2}{16EI}\\).","marks":1,"source":{"kind":"past","set":12,"question":10,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q10 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-12-011","src":"PAST-12-011","text":"If σ and τ are the normal and shear stresses respectively, find the minor principal stress.","options":[{"key":"a","text":"σ<sub>x</sub>/2 + √(σ<sub>x</sub><sup>2</sup>/4 − τ<sub>xy</sub><sup>2</sup>)"},{"key":"b","text":"σ<sub>x</sub>/2 − √(σ<sub>x2</sub>/4 + τ<sub>xy</sub><sup>2</sup>)"},{"key":"c","text":"σ<sub>x</sub>/2 − √(σ<sub>x</sub><sup>2</sup>/4 − τ<sub>xy</sub><sup>2</sup>)"},{"key":"d","text":"σ<sub>x</sub>/2 − √(σ<sub>x</sub><sup>2</sup>/4 + τ<sub>xy</sub><sup>2</sup>)"}],"answer":"d","explanation":"The minor principal stress is \\[\\sigma_2 = \\dfrac{\\sigma_x}{2} - \\sqrt{\\left(\\dfrac{\\sigma_x}{2}\\right)^2 + \\tau_{xy}^2}\\] The major principal stress takes the + sign.","marks":1,"source":{"kind":"past","set":12,"question":11,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q11 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-12-012","src":"PAST-12-012","text":"A plane truss has 11 members and 8 joints. How many additional members are needed to make the truss stable?","options":[{"key":"a","text":"0"},{"key":"b","text":"1"},{"key":"c","text":"2"},{"key":"d","text":"3"}],"answer":"c","explanation":"A simple plane truss needs \\[m = 2j - 3 = 2 \\times 8 - 3 = 13\\] members, so 2 more are required.","marks":1,"source":{"kind":"past","set":12,"question":12,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q12 · 1 mark"},"topic":"ACiE0405"},{"id":"PAST-12-036","src":"PAST-12-036","text":"The factor by which the applied moment is multiplied to obtain the end moment at the far end of a member is known as the","options":[{"key":"a","text":"distribution factor"},{"key":"b","text":"carryover factor"},{"key":"c","text":"relative stiffness"},{"key":"d","text":"total relative stiffness"}],"answer":"b","explanation":"The carry-over factor (½ for a far end fixed, 0 for a far end pinned) gives the moment induced at the far end by a moment applied at the near end.","marks":1,"source":{"kind":"past","set":12,"question":36,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q36 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-12-038","src":"PAST-12-038","text":"What is the value of the effective length of a column with both ends fixed?","options":[{"key":"a","text":"L/2"},{"key":"b","text":"L/4"},{"key":"c","text":"2L"},{"key":"d","text":"L"}],"answer":"a","explanation":"Fixed–fixed columns have a theoretical effective length of L/2 (0.65L recommended in design).","marks":1,"source":{"kind":"past","set":12,"question":38,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q38 · 1 mark"},"topic":"ACiE0403"},{"id":"PAST-12-052","src":"PAST-12-052","text":"If a simply supported beam carries a UDL across the entire span, then the shear force","options":[{"key":"a","text":"changes linearly"},{"key":"b","text":"is maximum at the centre"},{"key":"c","text":"doesn't have a maximum value"},{"key":"d","text":"has a parabolic nature"}],"answer":"a","explanation":"Under UDL, \\[S = w\\left(\\dfrac{L}{2} - x\\right)\\] varies linearly from \\(+\\dfrac{wL}{2}\\) to \\(-\\dfrac{wL}{2}\\) and is zero at midspan. It is the bending moment that is parabolic.","marks":1,"source":{"kind":"past","set":12,"question":52,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q52 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-12-064","src":"PAST-12-064","text":"Given that the unsupported length of a column with both ends fixed is L, what will be the unsupported length of an equivalent column with one end fixed and the other end free?","options":[{"key":"a","text":"L"},{"key":"b","text":"L/2"},{"key":"c","text":"L/4"},{"key":"d","text":"L/8"}],"answer":"c","explanation":"Equal effective lengths require \\[\\dfrac{L}{2} = 2L'\\] (fixed-fixed against fixed-free), so \\(L' = \\dfrac{L}{4}\\).","marks":2,"source":{"kind":"past","set":12,"question":64,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q64 · 2 marks"},"topic":"ACiE0403"},{"id":"PAST-12-065","src":"PAST-12-065","text":"In the case of a simply supported I-section beam carrying a concentrated load at the mid span, what will be the length of the plastic hinge formed?","options":[{"key":"a","text":"L/2"},{"key":"b","text":"L/3"},{"key":"c","text":"L/4"},{"key":"d","text":"L/5"}],"answer":"d","explanation":"The plastic zone extends over \\[L\\left(1 - \\dfrac{1}{S}\\right)\\] where \\(S\\) is the shape factor. For a rectangle (\\(S = 1.5\\)) that is \\(\\dfrac{L}{3}\\). For I-sections (\\(S \\approx 1.12\\) to 1.25) it is much shorter, and the key takes \\(\\dfrac{L}{5}\\).","marks":2,"source":{"kind":"past","set":12,"question":65,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q65 · 2 marks"},"topic":"ACiE0406"}]},{"name":"Design of Structures","questions":[{"id":"PAST-12-001","src":"PAST-12-001","text":"When purlins are placed between panel points, the principal rafter is to be designed for","options":[{"key":"a","text":"axial compression and tension"},{"key":"b","text":"axial compression"},{"key":"c","text":"axial compression and bending moment"},{"key":"d","text":"axial tension and bending moment"}],"answer":"c","explanation":"The principal rafter is a compression member. Purlins between panel points load it transversely, so it must also be designed for the resulting bending moment.","marks":1,"source":{"kind":"past","set":12,"question":1,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q1 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-12-015","src":"PAST-12-015","text":"If enough water for workability of concrete is already added, then increasing the w/c ratio in the concrete results in","options":[{"key":"a","text":"strength will increase"},{"key":"b","text":"strength will decrease"},{"key":"c","text":"strength may increase or decrease"},{"key":"d","text":"strength is independent of the w/c ratio"}],"answer":"b","explanation":"By Abrams' law, strength falls as the w/c ratio rises, because the extra water leaves capillary pores after it evaporates.","marks":1,"source":{"kind":"past","set":12,"question":15,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q15 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-12-016","src":"PAST-12-016","text":"What nominal mix of concrete is required for roofing of RCC?","options":[{"key":"a","text":"M10"},{"key":"b","text":"M15"},{"key":"c","text":"M20"},{"key":"d","text":"M30"}],"answer":"c","explanation":"RCC roof slabs are normally cast in M20 (nominal 1:1.5:3), the minimum grade for reinforced concrete in most exposures.","marks":1,"source":{"kind":"past","set":12,"question":16,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q16 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-12-017","src":"PAST-12-017","text":"What is the maximum theoretical percentage of longitudinal reinforcement in an RCC column?","options":[{"key":"a","text":"6% of gross area"},{"key":"b","text":"4% of gross area"},{"key":"c","text":"5% of gross area"},{"key":"d","text":"2% of gross area"}],"answer":"a","explanation":"IS 456 limits column longitudinal steel to between 0.8% and 6% of the gross area, with 4% advised as a practical maximum.","marks":1,"source":{"kind":"past","set":12,"question":17,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q17 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-12-018","src":"PAST-12-018","text":"What is the name of the slab which is continuously supported on two (opposite) sides and carries load in one direction only?","options":[{"key":"a","text":"one way slab"},{"key":"b","text":"two-way slab"},{"key":"c","text":"torsional slab"},{"key":"d","text":"continuous slab"}],"answer":"a","explanation":"A slab supported on two opposite sides, or with L<sub>y</sub>/L<sub>x</sub> &gt; 2, bends in one direction only and is a one-way slab.","marks":1,"source":{"kind":"past","set":12,"question":18,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q18 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-12-023","src":"PAST-12-023","text":"On what sieve size must an aggregate be retained to be a fine aggregate?","options":[{"key":"a","text":"75 microns"},{"key":"b","text":"2.36 mm"},{"key":"c","text":"4.75 mm"},{"key":"d","text":"20 microns"}],"answer":"a","explanation":"Fine aggregate passes the 4.75 mm sieve and is retained on the 75 µm sieve. Finer material is silt and clay.","marks":1,"source":{"kind":"past","set":12,"question":23,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q23 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-12-037","src":"PAST-12-037","text":"What is the slenderness ratio of a 200 mm wall with RCC slab at the top and bottom, with 5 m length and 3.8 m of height?","options":[{"key":"a","text":"19"},{"key":"b","text":"9.5"},{"key":"c","text":"20"},{"key":"d","text":"25"}],"answer":"a","explanation":"The key uses the lesser of \\[\\dfrac{h}{t} = \\dfrac{3.8}{0.2} = 19\\] \\[\\dfrac{l}{t} = \\dfrac{5}{0.2} = 25\\] giving 19. IS 1905 would further take the effective height as \\(0.75H\\) for RCC slabs bearing on the wall.","marks":1,"source":{"kind":"past","set":12,"question":37,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q37 · 1 mark"},"topic":"ACiE0506"},{"id":"PAST-12-060","src":"PAST-12-060","text":"Provisions for live loads are made in which of the following IS codes?","options":[{"key":"a","text":"IS 875 I"},{"key":"b","text":"IS 875 II"},{"key":"c","text":"IS 1893"},{"key":"d","text":"IS 875 III"}],"answer":"b","explanation":"IS 875 Part 2 covers imposed (live) loads. Part 1 covers dead loads, Part 3 wind loads and IS 1893 earthquake loads.","marks":1,"source":{"kind":"past","set":12,"question":60,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q60 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-12-070","src":"PAST-12-070","text":"If the diameter of a rebar is D = 20 mm, what is the value of the anchorage length for a U-bend?","options":[{"key":"a","text":"320 mm"},{"key":"b","text":"160 mm"},{"key":"c","text":"80 mm"},{"key":"d","text":"480 mm"}],"answer":"a","explanation":"IS 456 credits a standard U-type (\\(180^\\circ\\)) hook with an anchorage value of \\[16\\phi = 16 \\times 20 = 320\\ \\text{mm}\\] A \\(90^\\circ\\) bend counts as \\(8\\phi\\).","marks":2,"source":{"kind":"past","set":12,"question":70,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q70 · 2 marks"},"topic":"ACiE0503"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-12-019","src":"PAST-12-019","text":"The placement of an intake is not optimal when it is placed in a","options":[{"key":"a","text":"natural channel"},{"key":"b","text":"navigation channel"},{"key":"c","text":"both a and b"},{"key":"d","text":"none"}],"answer":"c","explanation":"An intake should avoid navigation channels (traffic hazards) and main natural flow channels (floods, debris, shifting currents). It is placed where it is safe and draws good water.","marks":1,"source":{"kind":"past","set":12,"question":19,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q19 · 1 mark"},"topic":"ACiE0602"},{"id":"PAST-12-020","src":"PAST-12-020","text":"Below which DO value is the survival of aquatic life not possible?","options":[{"key":"a","text":"4 mg/L"},{"key":"b","text":"5 mg/L"},{"key":"c","text":"7 mg/L"},{"key":"d","text":"15 mg/L"}],"answer":"a","explanation":"Fish and most aquatic life need at least about 4 mg/L of dissolved oxygen. Below this they are stressed and die.","marks":1,"source":{"kind":"past","set":12,"question":20,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q20 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-12-021","src":"PAST-12-021","text":"For a rapidly growing population, which method of projection is preferred?","options":[{"key":"a","text":"Arithmetical increase method"},{"key":"b","text":"Geometrical increase method"},{"key":"c","text":"Incremental increase method"},{"key":"d","text":"Graphical method"}],"answer":"b","explanation":"Young, rapidly growing towns increase at a roughly constant percentage rate, which suits the geometrical (compound) increase method.","marks":1,"source":{"kind":"past","set":12,"question":21,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q21 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-12-022","src":"PAST-12-022","text":"What is the rate of filtration of a rapid sand filter?","options":[{"key":"a","text":"3000 - 6000 l/hr/m<sup>2</sup>"},{"key":"b","text":"100 - 200 l/hr/m<sup>2</sup>"},{"key":"c","text":"2000 - 4000 l/hr/m<sup>2</sup>"},{"key":"d","text":"5000 - 10000 l/hr/m<sup>2</sup>"}],"answer":"a","explanation":"Rapid sand filters run at about 3000-6000 litres per hour per m<sup>2</sup>. Slow sand filters run at 100-200 litres per hour per m<sup>2</sup>.","marks":1,"source":{"kind":"past","set":12,"question":22,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q22 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-12-024","src":"PAST-12-024","text":"What is the name of the sewer that collects water from a number of other large sewers or outlets?","options":[{"key":"a","text":"Intercepting sewer"},{"key":"b","text":"Force main"},{"key":"c","text":"Branch sewer"},{"key":"d","text":"Collecting sewer"}],"answer":"a","explanation":"An intercepting sewer runs across the ends of several large sewers or outfalls, collecting their flow and carrying it to the treatment works.","marks":1,"source":{"kind":"past","set":12,"question":24,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q24 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-12-025","src":"PAST-12-025","text":"When was the first environmental act introduced in Nepal?","options":[{"key":"a","text":"1997"},{"key":"b","text":"2001"},{"key":"c","text":"1994"},{"key":"d","text":"1993"}],"answer":"a","explanation":"Nepal's Environment Protection Act was enacted in 2053 BS (1997 AD), with its rules in 2054 BS. It was replaced by the 2076 BS (2019) Act.","marks":1,"source":{"kind":"past","set":12,"question":25,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q25 · 1 mark"},"topic":"ACiE0606"},{"id":"PAST-12-058","src":"PAST-12-058","text":"The per capita demand of water is calculated in litres","options":[{"key":"a","text":"per person per year"},{"key":"b","text":"per person per month"},{"key":"c","text":"per person per day"},{"key":"d","text":"per peak hour consumption"}],"answer":"c","explanation":"Per capita demand is expressed as litres per capita per day (lpcd): the annual average daily consumption divided by the population.","marks":1,"source":{"kind":"past","set":12,"question":58,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q58 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-12-068","src":"PAST-12-068","text":"Which ministry passes the DRM strategy?","options":[{"key":"a","text":"Ministry of Home Affairs"},{"key":"b","text":"Ministry of Defence"},{"key":"c","text":"Ministry of Disaster Risk Management"},{"key":"d","text":"Ministry of Tourism"}],"answer":"a","explanation":"Disaster risk management in Nepal falls under the Ministry of Home Affairs, whose NDRRMA prepares the national DRR policy and strategic action plan.","marks":2,"source":{"kind":"past","set":12,"question":68,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q68 · 2 marks"},"topic":"ACiE0606"},{"id":"PAST-12-080","src":"PAST-12-080","text":"If 40 ml of sewage is diluted to 240 ml of mixture, what is the TON value?","options":[{"key":"a","text":"1/6"},{"key":"b","text":"6"},{"key":"c","text":"5"},{"key":"d","text":"1/5"}],"answer":"b","explanation":"The threshold odour number is the total mixture volume divided by the sample volume: \\[\\text{TON} = \\dfrac{240}{40} = 6\\]","marks":2,"source":{"kind":"past","set":12,"question":80,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q80 · 2 marks"},"topic":"ACiE0601"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-12-026","src":"PAST-12-026","text":"What is consumptive use in terms of losses?","options":[{"key":"a","text":"Evaporation and transpiration"},{"key":"b","text":"Evaporation and infiltration"},{"key":"c","text":"Evaporation, infiltration and transpiration"},{"key":"d","text":"Evaporation and the conveyance losses"}],"answer":"a","explanation":"Consumptive use (evapotranspiration) is the water lost by evaporation from the soil and plant surfaces plus transpiration by the crop, together with a small amount built into plant tissue.","marks":1,"source":{"kind":"past","set":12,"question":26,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q26 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-12-027","src":"PAST-12-027","text":"Which hydraulic structure allows drainage to mix with the canal?","options":[{"key":"a","text":"canal outlet"},{"key":"b","text":"canal inlet"},{"key":"c","text":"modules"},{"key":"d","text":"none of the above"}],"answer":"b","explanation":"A canal inlet admits drainage or stream water into the canal, for small cross-drainage flows. Outlets and modules deliver canal water to the fields.","marks":1,"source":{"kind":"past","set":12,"question":27,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q27 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-12-028","src":"PAST-12-028","text":"What is the major point of difference between weirs and barrages?","options":[{"key":"a","text":"size of the structure"},{"key":"b","text":"size of the water channel"},{"key":"c","text":"presence of gates"},{"key":"d","text":"their usage/purpose"}],"answer":"c","explanation":"A weir raises water mainly by its fixed crest, with small shutters at most. A barrage raises and regulates the pond level by a series of gates over a low crest.","marks":1,"source":{"kind":"past","set":12,"question":28,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q28 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-12-029","src":"PAST-12-029","text":"If Q = 5 m<sup>3</sup>/s and the mean size of sediments is 0.5 mm, then what is the velocity using Lacey's formula?","options":[{"key":"a","text":"0.381 m/s"},{"key":"b","text":"0.281 m/s"},{"key":"c","text":"0.532 m/s"},{"key":"d","text":"0.617 m/s"}],"answer":"d","explanation":"The silt factor is \\(f = 1.76\\sqrt{0.5} = 1.245\\), so \\[\\begin{aligned} V &amp;= \\left(\\dfrac{Qf^2}{140}\\right)^{1{/}6} \\\\ &amp;= \\left(\\dfrac{5 \\times 1.549}{140}\\right)^{1{/}6} \\\\ &amp;\\approx 0.617\\ \\text{m/s} \\end{aligned}\\]","marks":1,"source":{"kind":"past","set":12,"question":29,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q29 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-12-030","src":"PAST-12-030","text":"Which material has the lowest safe exit gradient using Khosla's theory?","options":[{"key":"a","text":"fine sand"},{"key":"b","text":"coarse sand"},{"key":"c","text":"shingle"},{"key":"d","text":"boulders"}],"answer":"a","explanation":"Finer soils are more easily lifted by upward seepage. Khosla's safe exit gradients are about \\(\\dfrac{1}{6}\\) to \\(\\dfrac{1}{7}\\) for fine sand, \\(\\dfrac{1}{5}\\) to \\(\\dfrac{1}{6}\\) for coarse sand and \\(\\dfrac{1}{4}\\) to \\(\\dfrac{1}{5}\\) for shingle.","marks":1,"source":{"kind":"past","set":12,"question":30,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q30 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-12-033","src":"PAST-12-033","text":"In modern days, which type of gates are mostly used in hydraulic structures?","options":[{"key":"a","text":"Sliding"},{"key":"b","text":"Roller"},{"key":"c","text":"Fixed"},{"key":"d","text":"Wheel"}],"answer":"c","explanation":"The key's answer is fixed (fixed-wheel) gates, the common vertical-lift gates of modern spillways and intakes. Radial gates are also widely used.","marks":1,"source":{"kind":"past","set":12,"question":33,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q33 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-12-059","src":"PAST-12-059","text":"When a canal is taken as an example, what factor causes its water logging?","options":[{"key":"a","text":"seepage of water from high land"},{"key":"b","text":"seepage through the canals"},{"key":"c","text":"over and intensive irrigation"},{"key":"d","text":"excessive rain"}],"answer":"b","explanation":"Seepage from unlined canals continuously recharges the groundwater and raises the water table. This is the canal's own main contribution to waterlogging.","marks":1,"source":{"kind":"past","set":12,"question":59,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q59 · 1 mark"},"topic":"ACiE0706"}]},{"name":"Hydropower","questions":[{"id":"PAST-12-031","src":"PAST-12-031","text":"Uplift pressure is important for the stability of which type of dam?","options":[{"key":"a","text":"Earthen dam"},{"key":"b","text":"Concrete dam"},{"key":"c","text":"Cofferdam"},{"key":"d","text":"Buttress dam"}],"answer":"b","explanation":"Uplift acts under the base of a concrete (masonry) gravity dam and reduces its effective weight, which matters for overturning and sliding. Drains and grout curtains are provided to control it.","marks":1,"source":{"kind":"past","set":12,"question":31,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q31 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-12-034","src":"PAST-12-034","text":"The coincidence factor is the reciprocal of","options":[{"key":"a","text":"total demand"},{"key":"b","text":"load factor"},{"key":"c","text":"diversity factor"},{"key":"d","text":"plant factor"}],"answer":"c","explanation":"The coincidence factor is the system peak ÷ the sum of the individual peaks. The diversity factor is the inverse ratio, so each is the reciprocal of the other.","marks":1,"source":{"kind":"past","set":12,"question":34,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q34 · 1 mark"},"topic":"ACiE0802"},{"id":"PAST-12-035","src":"PAST-12-035","text":"The power of a centrifugal pump is proportional to","options":[{"key":"a","text":"D<sup>2</sup>"},{"key":"b","text":"D<sup>3</sup>"},{"key":"c","text":"D<sup>4</sup>"},{"key":"d","text":"None"}],"answer":"d","explanation":"By the affinity laws \\[P \\propto \\rho N^3D^5\\] (\\(Q \\propto ND^3\\), \\(H \\propto N^2D^2\\)), so at a given speed power varies as \\(D^5\\), which is none of the options. The source key gives (b).","marks":1,"source":{"kind":"past","set":12,"question":35,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q35 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-12-039","src":"PAST-12-039","text":"Which of the following best describes the hydraulic efficiency of a turbine?","options":[{"key":"a","text":"Fluid power transferred to the runners / fluid power transferred to the vanes"},{"key":"b","text":"Fluid power transferred to the vane / fluid power transferred to the runner"},{"key":"c","text":"Fluid power transferred to the runner / shaft power"},{"key":"d","text":"Fluid power transferred to the runners / power available at the inlet to the vanes"}],"answer":"d","explanation":"Hydraulic efficiency is the power delivered by the water to the runner divided by the water power available at the inlet (\\(\\rho gQH\\)). Mechanical efficiency is the shaft power divided by the runner power.","marks":1,"source":{"kind":"past","set":12,"question":39,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q39 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-12-056","src":"PAST-12-056","text":"The use of a draft tube in a reaction turbine helps to","options":[{"key":"a","text":"prevent the air from entering"},{"key":"b","text":"increase the flow rate"},{"key":"c","text":"convert KE to pressure energy"},{"key":"d","text":"prevent eddies"}],"answer":"c","explanation":"The diverging draft tube slows the water leaving the runner, recovering its kinetic energy as pressure (suction) head. It also lets the turbine be set above the tailwater.","marks":1,"source":{"kind":"past","set":12,"question":56,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q56 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-12-076","src":"PAST-12-076","text":"A power generating station has a plant capacity of 200 MW and a maximum power demand of 150 MW. If the average power generation is 110 MW, then find the load factor and capacity factor respectively.","options":[{"key":"a","text":"0.55 and 0.73"},{"key":"b","text":"0.75 and 0.65"},{"key":"c","text":"0.73 and 0.55"},{"key":"d","text":"0.65 and 0.55"}],"answer":"c","explanation":"The load factor uses the peak and the capacity factor the installed capacity: \\[\\text{LF} = \\dfrac{110}{150} = 0.73\\] \\[\\text{CF} = \\dfrac{110}{200} = 0.55\\]","marks":2,"source":{"kind":"past","set":12,"question":76,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q76 · 2 marks"},"topic":"ACiE0802"}]},{"name":"Transportation","questions":[{"id":"PAST-12-002","src":"PAST-12-002","text":"For sandy soils, the most common method of stabilization is","options":[{"key":"a","text":"soil-cement"},{"key":"b","text":"mechanical"},{"key":"c","text":"soil-lime"},{"key":"d","text":"soil-bitumen"}],"answer":"a","explanation":"Cement binds cohesionless sandy soils well, so soil-cement is the usual stabiliser for them. Lime needs clay minerals to react with, and bitumen is used mainly for waterproofing.","marks":1,"source":{"kind":"past","set":12,"question":2,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q2 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-12-003","src":"PAST-12-003","text":"The rate of stretching bitumen in the ductility test is","options":[{"key":"a","text":"5 mm/min"},{"key":"b","text":"5 cm/min"},{"key":"c","text":"10 cm/min"},{"key":"d","text":"10 mm/min"}],"answer":"b","explanation":"The briquette is pulled apart at 50 mm (5 cm) per minute at 27°C. The distance at which the thread breaks, in cm, is the ductility.","marks":1,"source":{"kind":"past","set":12,"question":3,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q3 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-12-032","src":"PAST-12-032","text":"Which shape is optimal for a surface drain?","options":[{"key":"a","text":"Circular"},{"key":"b","text":"Trapezoidal"},{"key":"c","text":"Triangular"},{"key":"d","text":"Rectangular"}],"answer":"b","explanation":"Trapezoidal open drains are hydraulically efficient, have stable side slopes and are easy to build and clean, so they are the usual roadside surface drains.","marks":1,"source":{"kind":"past","set":12,"question":32,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q32 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-12-040","src":"PAST-12-040","text":"The improper alignment of a highway does not cause which of the following?","options":[{"key":"a","text":"Cost increase"},{"key":"b","text":"Increase in the probability of accidents"},{"key":"c","text":"Traffic problems"},{"key":"d","text":"Fatigue cracking"}],"answer":"d","explanation":"Poor alignment raises construction and operating costs, accidents and traffic problems. Fatigue cracking comes from repeated wheel loads on the pavement structure, not from alignment.","marks":1,"source":{"kind":"past","set":12,"question":40,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q40 · 1 mark"},"topic":"ACiE0901"},{"id":"PAST-12-041","src":"PAST-12-041","text":"Find the value of the radius of curvature if the degree of curve D is given as 23.76.","options":[{"key":"a","text":"241.16 m"},{"key":"b","text":"214.16 m"},{"key":"c","text":"271.23 m"},{"key":"d","text":"217.23 m"}],"answer":"a","explanation":"With the 100-unit standard arc, \\[\\begin{aligned} R &amp;= \\dfrac{5729.58}{D} = \\dfrac{5729.58}{23.76} \\\\ &amp;\\approx 241.1 \\end{aligned}\\] matching option (a). With a 30 m arc, \\(R = \\dfrac{1718.9}{D}\\). With a 30 m arc, \\(R = \\dfrac{1718.9}{D}\\).","marks":1,"source":{"kind":"past","set":12,"question":41,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q41 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-12-042","src":"PAST-12-042","text":"What is the effect of using traffic signals at intersections?","options":[{"key":"a","text":"reduce right angle collision as well as rear end collision"},{"key":"b","text":"reduce rear end collision but may increase right angle collision"},{"key":"c","text":"reduce right angle collision but may increase rear end collision"},{"key":"d","text":"none of the above"}],"answer":"c","explanation":"Signals separate crossing streams in time, sharply reducing right-angle collisions. Sudden stops on the amber, however, tend to increase rear-end collisions.","marks":1,"source":{"kind":"past","set":12,"question":42,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q42 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-12-043","src":"PAST-12-043","text":"What is the brake reaction time of a normal driver?","options":[{"key":"a","text":"1.5 sec"},{"key":"b","text":"2.5 sec"},{"key":"c","text":"3 sec"},{"key":"d","text":"4 sec"}],"answer":"b","explanation":"IRC adopts a total perception–brake reaction time of 2.5 s for calculating stopping sight distance.","marks":1,"source":{"kind":"past","set":12,"question":43,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q43 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-12-079","src":"PAST-12-079","text":"The maximum spacing of contraction joints in unreinforced concrete slabs for a slab thickness of 20 cm is","options":[{"key":"a","text":"4.5 m"},{"key":"b","text":"15 m"},{"key":"c","text":"10 m"},{"key":"d","text":"20 m"}],"answer":"a","explanation":"IRC:58 limits the contraction-joint spacing of plain (unreinforced) concrete slabs to about 4.5 m, to control shrinkage and warping cracks. Reinforced slabs allow wider spacing.","marks":2,"source":{"kind":"past","set":12,"question":79,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q79 · 2 marks"},"topic":"ACiE0905"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-12-044","src":"PAST-12-044","text":"Paper is designated by which letter?","options":[{"key":"a","text":"A"},{"key":"b","text":"D"},{"key":"c","text":"F"},{"key":"d","text":"P"}],"answer":"a","explanation":"Drawing sheets follow the ISO A-series sizes (A0, A1, … A4), each half the area of the one before.","marks":1,"source":{"kind":"past","set":12,"question":44,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q44 · 1 mark"},"topic":"AALL1001"},{"id":"PAST-12-045","src":"PAST-12-045","text":"What is the expression for the sinking fund factor?","options":[{"key":"a","text":"i/(1+i)<sup>n</sup> − 1"},{"key":"b","text":"i/(1+i)<sup>n</sup> + 1"},{"key":"c","text":"i/[(1+i)<sup>n</sup> − 1]"},{"key":"d","text":"i/[(1+i)<sup>n</sup> + 1]"}],"answer":"c","explanation":"The sinking fund factor converts a future sum into equal year-end deposits: \\[\\left(\\dfrac{A}{F}, i, n\\right) = \\dfrac{i}{(1 + i)^n - 1}\\] The capital recovery factor is SFF + \\(i\\).","marks":1,"source":{"kind":"past","set":12,"question":45,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q45 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-12-046","src":"PAST-12-046","text":"Which of the following best defines free float?","options":[{"key":"a","text":"The total amount of time a task can be delayed without affecting the final project delivery date"},{"key":"b","text":"The amount of time a task can be delayed without impacting other tasks in the path"},{"key":"c","text":"both a and b"},{"key":"d","text":"neither a nor b"}],"answer":"b","explanation":"Free float is the delay possible without delaying the early start of any succeeding activity. Total float, option (a), is the delay possible without delaying the project.","marks":1,"source":{"kind":"past","set":12,"question":46,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q46 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-12-047","src":"PAST-12-047","text":"What term denotes the reduction of risk to a threshold level?","options":[{"key":"a","text":"mitigation"},{"key":"b","text":"acceptance"},{"key":"c","text":"transfer"},{"key":"d","text":"none of the above"}],"answer":"a","explanation":"Risk mitigation lowers the probability or impact of a risk to an acceptable (threshold) level. Acceptance leaves it as it is, and transfer shifts it to another party.","marks":1,"source":{"kind":"past","set":12,"question":47,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q47 · 1 mark"},"topic":"AALL1004"},{"id":"PAST-12-048","src":"PAST-12-048","text":"How many categories of NEA memberships are there?","options":[{"key":"a","text":"3"},{"key":"b","text":"5"},{"key":"c","text":"7"},{"key":"d","text":"2"}],"answer":"a","explanation":"Per the source key, the Nepal Engineers' Association has three membership categories. This is an institution-specific fact.","marks":1,"source":{"kind":"past","set":12,"question":48,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q48 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-12-050","src":"PAST-12-050","text":"Sealed quotations are used for projects up to","options":[{"key":"a","text":"20 million"},{"key":"b","text":"2 million"},{"key":"c","text":"1 million"},{"key":"d","text":"5 million"}],"answer":"b","explanation":"Under Nepal's public procurement rules at the time, procurement up to about Rs 20 lakh (2 million) could be made by sealed quotation. Larger contracts need tenders.","marks":1,"source":{"kind":"past","set":12,"question":50,"marks":1,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q50 · 1 mark"},"topic":"AALL1004"},{"id":"PAST-12-066","src":"PAST-12-066","text":"If the EST = 5, LST = 7 and duration = 1, then what is TF?","options":[{"key":"a","text":"2"},{"key":"b","text":"0"},{"key":"c","text":"1"},{"key":"d","text":"3"}],"answer":"a","explanation":"The total float is \\[\\begin{aligned} \\text{TF} &amp;= \\text{LST} - \\text{EST} \\\\ &amp;= 7 - 5 = 2 \\end{aligned}\\] (equivalently LFT minus EFT).","marks":2,"source":{"kind":"past","set":12,"question":66,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q66 · 2 marks"},"topic":"AALL1003"},{"id":"PAST-12-069","src":"PAST-12-069","text":"Who appoints the chairman of NEC?","options":[{"key":"a","text":"the Government of Nepal"},{"key":"b","text":"the President of Nepal"},{"key":"c","text":"Ministry of Home Affairs"},{"key":"d","text":"the Supreme Court"}],"answer":"a","explanation":"Under the NEC Act, the Government of Nepal nominates the chairperson of the Nepal Engineering Council.","marks":2,"source":{"kind":"past","set":12,"question":69,"marks":2,"date":"2080 Mangsir 23","shift":"2nd shift","reference":"Past Paper Set 12, Q69 · 2 marks"},"topic":"AALL1006"}]}]};
